//! Merges engine-regenerated OOXML parts with byte-preserved unknown parts and reconciles OPC metadata.

use crate::error::XlsxError;
use crate::preserve::{PreservedPackage, RawRelationship, parse_relationships};
use quick_xml::events::Event;
use quick_xml::{Reader, XmlVersion};
use std::collections::{BTreeMap, HashMap};
use std::io::{Cursor, Read, Write};
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

static TMP_COUNTER: AtomicU64 = AtomicU64::new(1);

/// Merges `engine_xlsx_bytes` (generated by `SheetEngine::to_xlsx_bytes`) with `preserved`,
/// returning a valid, byte-preserving `.xlsx` / `.xlsm` ZIP archive in memory.
pub fn merge_engine_with_preserved(
    engine_xlsx_bytes: &[u8],
    preserved: &PreservedPackage,
) -> Result<Vec<u8>, XlsxError> {
    if preserved.unknown_parts.is_empty()
        && preserved.workbook_content_type.is_none()
        && preserved.extra_workbook_rels.is_empty()
        && preserved.sheet_attachments.is_empty()
    {
        return Ok(engine_xlsx_bytes.to_vec());
    }

    let mut engine_zip = zip::ZipArchive::new(Cursor::new(engine_xlsx_bytes))?;
    let mut parts: BTreeMap<String, (Vec<u8>, bool)> = BTreeMap::new();

    for idx in 0..engine_zip.len() {
        let mut file = engine_zip.by_index(idx)?;
        if file.is_dir() {
            continue;
        }
        let name = file.name()?.trim_start_matches('/').to_string();
        let mut buf = Vec::with_capacity(file.size() as usize);
        file.read_to_end(&mut buf)?;
        parts.insert(name, (buf, false));
    }

    // 1. Reconcile `[Content_Types].xml`.
    if let Some((ct_bytes, _)) = parts.get_mut("[Content_Types].xml") {
        let updated = reconcile_content_types(ct_bytes, preserved)?;
        *ct_bytes = updated.into_bytes();
    }

    // 2. Reconcile `_rels/.rels`.
    if !preserved.extra_root_rels.is_empty()
        && let Some((rels_bytes, _)) = parts.get_mut("_rels/.rels")
    {
        let (updated, _) = append_relationships(rels_bytes, &preserved.extra_root_rels)?;
        *rels_bytes = updated.into_bytes();
    }

    // 3. Reconcile `xl/_rels/workbook.xml.rels` and `xl/workbook.xml`.
    let mut wb_rid_map: HashMap<String, String> = HashMap::new();
    if !preserved.extra_workbook_rels.is_empty()
        && let Some((wb_rels_bytes, _)) = parts.get_mut("xl/_rels/workbook.xml.rels")
    {
        let (updated, map) = append_relationships(wb_rels_bytes, &preserved.extra_workbook_rels)?;
        wb_rid_map = map;
        *wb_rels_bytes = updated.into_bytes();
    }

    let current_sheets = match parts.get("xl/workbook.xml") {
        Some((wb_bytes, _)) => extract_current_sheet_map(wb_bytes)?,
        None => Vec::new(),
    };

    if let Some((wb_bytes, _)) = parts.get_mut("xl/workbook.xml") {
        let updated = reconcile_workbook_xml(wb_bytes, preserved, &wb_rid_map)?;
        *wb_bytes = updated.into_bytes();
    }

    // 4. Reconcile each surviving worksheet's `.xml.rels` and trailing anchor tags.
    for (sheet_index, sheet_id) in current_sheets {
        let Some(attach) = preserved.sheet_attachments.get(&sheet_id) else {
            continue;
        };
        let sheet_num = sheet_index + 1;
        let rels_key = format!("xl/worksheets/_rels/sheet{sheet_num}.xml.rels");
        let existing_rels = parts.get(&rels_key).map(|(b, _)| b.as_slice()).unwrap_or(
            br#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>"#,
        );
        let (updated_rels, sheet_rid_map) =
            append_relationships(existing_rels, &attach.extra_rels)?;
        if !attach.extra_rels.is_empty() {
            parts.insert(rels_key, (updated_rels.into_bytes(), false));
        }

        let ws_key = format!("xl/worksheets/sheet{sheet_num}.xml");
        if let Some((ws_bytes, _)) = parts.get_mut(&ws_key) {
            let updated_ws = reconcile_worksheet_xml(ws_bytes, attach, &sheet_rid_map)?;
            *ws_bytes = updated_ws.into_bytes();
        }
    }

    // 5. Insert all preserved unknown parts byte-for-byte (never overwriting engine-managed parts).
    for (path, preserved_part) in &preserved.unknown_parts {
        parts.insert(
            path.clone(),
            (
                preserved_part.bytes.clone(),
                preserved_part.stored_uncompressed,
            ),
        );
    }

    // 6. Serialize merged ZIP archive and validate readability.
    let mut cursor = Cursor::new(Vec::new());
    {
        let mut writer = zip::ZipWriter::new(&mut cursor);
        let deflate_opts = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Deflated);
        let stored_opts = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Stored);

        for (path, (payload, stored)) in &parts {
            let opts = if *stored { stored_opts } else { deflate_opts };
            writer.start_file(path, opts)?;
            writer.write_all(payload)?;
        }
        writer.finish()?;
    }

    let out_bytes = cursor.into_inner();
    validate_zip_archive(&out_bytes)?;
    Ok(out_bytes)
}

/// Atomically writes `bytes` to `path` via a sibling temporary file, `sync_all`, ZIP validation, and `rename`.
pub fn atomic_write_xlsx(path: &Path, bytes: &[u8]) -> Result<(), XlsxError> {
    validate_zip_archive(bytes)?;
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    std::fs::create_dir_all(parent)?;
    let stem = path
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "workbook.xlsx".to_string());
    let pid = std::process::id();
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seq = TMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let tmp_path = parent.join(format!(".{stem}.{pid}.{nanos}.{seq}.tmp"));

    let write_res = (|| -> std::io::Result<()> {
        let mut file = std::fs::File::create(&tmp_path)?;
        file.write_all(bytes)?;
        file.sync_all()?;
        Ok(())
    })();
    if let Err(err) = write_res {
        let _ = std::fs::remove_file(&tmp_path);
        return Err(XlsxError::Io(err));
    }
    if let Err(err) = std::fs::rename(&tmp_path, path) {
        let _ = std::fs::remove_file(&tmp_path);
        return Err(XlsxError::Io(err));
    }
    Ok(())
}

fn validate_zip_archive(bytes: &[u8]) -> Result<(), XlsxError> {
    let archive = zip::ZipArchive::new(Cursor::new(bytes))
        .map_err(|e| XlsxError::Integrity(format!("invalid output ZIP container: {e}")))?;
    if archive.is_empty() {
        return Err(XlsxError::Integrity("output ZIP archive is empty".into()));
    }
    Ok(())
}

fn reconcile_content_types(
    engine_ct_bytes: &[u8],
    preserved: &PreservedPackage,
) -> Result<String, XlsxError> {
    let mut xml = std::str::from_utf8(engine_ct_bytes)
        .map_err(|e| XlsxError::Xml(e.to_string()))?
        .to_string();

    if let Some(ref orig_wb_ct) = preserved.workbook_content_type {
        xml = xml.replace(
            r#"PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml""#,
            &format!(r#"PartName="/xl/workbook.xml" ContentType="{orig_wb_ct}""#),
        );
    }

    let mut additions = String::new();
    for (ext, ct) in &preserved.extra_content_type_defaults {
        let needle = format!(r#"Extension="{ext}""#);
        if !xml.contains(&needle) {
            additions.push_str(&format!(
                r#"<Default Extension="{ext}" ContentType="{ct}"/>"#
            ));
        }
    }
    for (part, ct) in &preserved.extra_content_type_overrides {
        let needle = format!(r#"PartName="{part}""#);
        if !xml.contains(&needle) {
            additions.push_str(&format!(
                r#"<Override PartName="{part}" ContentType="{ct}"/>"#
            ));
        }
    }

    if !additions.is_empty() {
        xml = inject_before_closing(&xml, "</Types>", &additions)?;
    }
    Ok(xml)
}

fn append_relationships(
    existing_rels_bytes: &[u8],
    extra: &[RawRelationship],
) -> Result<(String, HashMap<String, String>), XlsxError> {
    let existing_xml =
        std::str::from_utf8(existing_rels_bytes).map_err(|e| XlsxError::Xml(e.to_string()))?;
    let parsed = parse_relationships(existing_rels_bytes)?;
    let mut max_num: u32 = 0;
    for r in &parsed {
        if let Some(num) = r
            .orig_id
            .strip_prefix("rId")
            .and_then(|s| s.parse::<u32>().ok())
        {
            max_num = max_num.max(num);
        }
    }

    let mut rid_map = HashMap::new();
    let mut appended = String::new();
    for rel in extra {
        max_num += 1;
        let new_id = format!("rId{max_num}");
        rid_map.insert(rel.orig_id.clone(), new_id.clone());
        let mode_attr = match &rel.target_mode {
            Some(m) => format!(r#" TargetMode="{m}""#),
            None => String::new(),
        };
        appended.push_str(&format!(
            r#"<Relationship Id="{new_id}" Type="{}" Target="{}"{mode_attr}/>"#,
            rel.rel_type, rel.target
        ));
    }

    if appended.is_empty() {
        return Ok((existing_xml.to_string(), rid_map));
    }

    let merged = if existing_xml.contains("</Relationships>") {
        inject_before_closing(existing_xml, "</Relationships>", &appended)?
    } else if let Some(self_close) = existing_xml.rfind("/>") {
        let mut s = String::with_capacity(existing_xml.len() + appended.len() + 20);
        s.push_str(&existing_xml[..self_close]);
        s.push('>');
        s.push_str(&appended);
        s.push_str("</Relationships>");
        s
    } else {
        return Err(XlsxError::Xml(
            "malformed .rels XML missing </Relationships>".into(),
        ));
    };

    Ok((merged, rid_map))
}

fn extract_current_sheet_map(wb_bytes: &[u8]) -> Result<Vec<(usize, u32)>, XlsxError> {
    let mut reader = Reader::from_reader(wb_bytes);
    let mut buf = Vec::new();
    let mut out = Vec::new();
    let mut idx = 0usize;

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(e) | Event::Start(e)) if e.local_name().as_ref() == "sheet" => {
                let mut sid = 0u32;
                for attr in e.attributes().with_checks(false) {
                    let attr = attr.map_err(|err| XlsxError::Xml(err.to_string()))?;
                    if attr.key.local_name().as_ref() == "sheetId"
                        && let Ok(val) = attr.normalized_value(XmlVersion::Implicit1_0)
                        && let Ok(parsed) = val.parse::<u32>()
                    {
                        sid = parsed;
                    }
                }
                out.push((idx, sid));
                idx += 1;
            }
            Ok(Event::Eof) => break,
            Err(err) => return Err(XlsxError::Xml(err.to_string())),
            _ => {}
        }
        buf.clear();
    }
    Ok(out)
}

fn reconcile_workbook_xml(
    wb_bytes: &[u8],
    preserved: &PreservedPackage,
    wb_rid_map: &HashMap<String, String>,
) -> Result<String, XlsxError> {
    let mut xml = std::str::from_utf8(wb_bytes)
        .map_err(|e| XlsxError::Xml(e.to_string()))?
        .to_string();

    if let Some(ref wb_pr) = preserved.workbook_pr_xml
        && !xml.contains("<workbookPr")
        && let Some(bv_pos) = xml.find("<bookViews>")
    {
        xml.insert_str(bv_pos, wb_pr);
    }

    let mut trailing = String::new();
    if !preserved.pivot_caches.is_empty() {
        trailing.push_str("<pivotCaches>");
        for pc in &preserved.pivot_caches {
            let mapped = wb_rid_map.get(&pc.orig_rid).unwrap_or(&pc.orig_rid);
            trailing.push_str(&format!(
                r#"<pivotCache cacheId="{}" r:id="{mapped}"/>"#,
                pc.cache_id
            ));
        }
        trailing.push_str("</pivotCaches>");
    }

    if !preserved.workbook_ext_blocks.is_empty() {
        trailing.push_str("<extLst>");
        for block in &preserved.workbook_ext_blocks {
            trailing.push_str(&remap_rids_in_xml(block, wb_rid_map));
        }
        trailing.push_str("</extLst>");
    }

    if !trailing.is_empty() {
        xml = inject_before_closing(&xml, "</workbook>", &trailing)?;
    }
    Ok(xml)
}

fn reconcile_worksheet_xml(
    ws_bytes: &[u8],
    attach: &crate::preserve::SheetAttachments,
    sheet_rid_map: &HashMap<String, String>,
) -> Result<String, XlsxError> {
    let mut xml = std::str::from_utf8(ws_bytes)
        .map_err(|e| XlsxError::Xml(e.to_string()))?
        .to_string();

    // OOXML CT_Worksheet sequence order before `extLst`:
    // `... hyperlinks? -> pageMargins? -> drawing? -> legacyDrawing? -> tableParts? -> extLst?`
    let mut pre_ext = String::new();
    if let Some(ref orig_d) = attach.drawing_orig_rid
        && let Some(mapped) = sheet_rid_map.get(orig_d)
    {
        pre_ext.push_str(&format!(r#"<drawing r:id="{mapped}"/>"#));
    }
    if let Some(ref orig_ld) = attach.legacy_drawing_orig_rid
        && let Some(mapped) = sheet_rid_map.get(orig_ld)
    {
        pre_ext.push_str(&format!(r#"<legacyDrawing r:id="{mapped}"/>"#));
    }
    if !attach.table_part_orig_rids.is_empty() {
        let mapped_parts: Vec<String> = attach
            .table_part_orig_rids
            .iter()
            .filter_map(|orig| sheet_rid_map.get(orig))
            .map(|m| format!(r#"<tablePart r:id="{m}"/>"#))
            .collect();
        if !mapped_parts.is_empty() {
            pre_ext.push_str(&format!(
                r#"<tableParts count="{}">{}</tableParts>"#,
                mapped_parts.len(),
                mapped_parts.join("")
            ));
        }
    }

    if !pre_ext.is_empty() {
        if let Some(ext_pos) = xml.rfind("<extLst>") {
            xml.insert_str(ext_pos, &pre_ext);
        } else {
            xml = inject_before_closing(&xml, "</worksheet>", &pre_ext)?;
        }
    }

    if !attach.preserved_ext_blocks.is_empty() {
        let mut ext_inner = String::new();
        for block in &attach.preserved_ext_blocks {
            ext_inner.push_str(&remap_rids_in_xml(block, sheet_rid_map));
        }
        if xml.contains("</extLst>") {
            xml = inject_before_closing(&xml, "</extLst>", &ext_inner)?;
        } else {
            let wrapped = format!("<extLst>{ext_inner}</extLst>");
            xml = inject_before_closing(&xml, "</worksheet>", &wrapped)?;
        }
    }

    Ok(xml)
}

/// Safely remaps `r:id="rIdX"` tokens inside a preserved `<ext>` block using a two-pass placeholder
/// so chained mappings (`rId1 -> rId2`, `rId2 -> rId3`) never collide.
fn remap_rids_in_xml(snippet: &str, rid_map: &HashMap<String, String>) -> String {
    if rid_map.is_empty() {
        return snippet.to_string();
    }
    let mut stage1 = snippet.to_string();
    for (idx, orig) in rid_map.keys().enumerate() {
        let from = format!(r#"r:id="{orig}""#);
        let token = format!(r#"r:id="__ORDIA_RID_{idx}__""#);
        stage1 = stage1.replace(&from, &token);
    }
    for (idx, (_orig, mapped)) in rid_map.iter().enumerate() {
        let token = format!(r#"r:id="__ORDIA_RID_{idx}__""#);
        let to = format!(r#"r:id="{mapped}""#);
        stage1 = stage1.replace(&token, &to);
    }
    stage1
}

fn inject_before_closing(
    xml: &str,
    closing_tag: &str,
    addition: &str,
) -> Result<String, XlsxError> {
    let Some(pos) = xml.rfind(closing_tag) else {
        return Err(XlsxError::Xml(format!(
            "missing closing tag `{closing_tag}` in OOXML document"
        )));
    };
    let mut out = String::with_capacity(xml.len() + addition.len());
    out.push_str(&xml[..pos]);
    out.push_str(addition);
    out.push_str(&xml[pos..]);
    Ok(out)
}
